drills.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  01 · validate a signup★★☆ core
//  concepts: validation · ValidationProblemDetails errors
// ─────────────────────────────────────────────────────────────────────────
//
//  Every failed rule, keyed by field, in one response.

using static Bootcamp.Check;

Dictionary<string, string[]> Validate(SignupDto dto)
{
    var errors = new Dictionary<string, List<string>>();
    void Add(string field, string message)
    {
        if (!errors.TryGetValue(field, out var list)) errors[field] = list = new List<string>();
        list.Add(message);
    }
    if (string.IsNullOrWhiteSpace(dto.Email)) Add("Email", "Email is required.");
    else
    {
        var parts = dto.Email.Trim().Split('@');
        if (parts.Length != 2 || parts[0].Length == 0 || parts[1].Length == 0) Add("Email", "Email is not a valid address.");
    }
    if (string.IsNullOrWhiteSpace(dto.Name)) Add("Name", "Name is required.");
    else if (dto.Name.Trim().Length > 50) Add("Name", "Name must be at most 50 characters.");
    if (dto.Age is { } age && (age < 13 || age > 120)) Add("Age", "Age must be between 13 and 120.");
    foreach (var role in dto.Roles ?? Array.Empty<string>())
        if (role is not ("reader" or "writer")) Add("Roles", $"Unknown role '{role}'.");
    return errors.ToDictionary(e => e.Key, e => e.Value.ToArray());
}

drills.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("a valid signup has no errors", () =>
    Eq(Validate(new SignupDto("ana@example.com", "Ana", 30, new[] { "reader" })).Count, 0));

Test("every problem is reported, keyed by field", () =>
{
    var errors = Validate(new SignupDto(" ", "Ana", 9, new[] { "admin" }));
    Eq(errors.Keys.OrderBy(k => k, StringComparer.Ordinal).ToList(), new[] { "Age", "Email", "Roles" });
    Eq(errors["Email"], new[] { "Email is required." });
    Eq(errors["Age"], new[] { "Age must be between 13 and 120." });
    Eq(errors["Roles"], new[] { "Unknown role 'admin'." });
});

Test("email format and name length", () =>
{
    var errors = Validate(new SignupDto("ana@@x", new string('n', 51), null, null));
    Eq(errors["Email"], new[] { "Email is not a valid address." });
    Eq(errors["Name"], new[] { "Name must be at most 50 characters." });
});

Test("several bad roles add several messages", () =>
    Eq(Validate(new SignupDto("a@b.io", "Ana", null, new[] { "writer", "root", "Reader" }))["Roles"], new[] { "Unknown role 'root'.", "Unknown role 'Reader'." }));

Test("optional fields may be missing; edges are inclusive (boundary)", () =>
{
    Eq(Validate(new SignupDto("a@b.io", "Ana", null, null)).Count, 0);
    Eq(Validate(new SignupDto("a@b.io", "Ana", 13, null)).Count, 0);
    Eq(Validate(new SignupDto("a@b.io", new string('n', 50), 120, null)).Count, 0);
    Ok(Validate(new SignupDto(null, null, null, null)).ContainsKey("Name"), "a null name is required");
});

drills.explanation:
Collect messages into a per-field list instead of returning at the first failure, then convert to the `string[]` shape of `ValidationProblemDetails.Errors`:

```csharp
void Add(string field, string message)
{
    if (!errors.TryGetValue(field, out var list)) errors[field] = list = new List<string>();
    list.Add(message);
}
// ... each rule calls Add ...
return errors.ToDictionary(e => e.Key, e => e.Value.ToArray());
```

In a minimal API the result plugs straight into `Results.ValidationProblem(errors)`. Returning early after the missing email passes the first test and fails "every problem is reported, keyed by field". Comparing roles case-insensitively fails "several bad roles add several messages": the spec wants `Reader` rejected, so match the exact lower-case strings with `role is not ("reader" or "writer")`.

